/* OIBUNG WORLD — original AI-assisted cinematic source artwork, optimized as WebP.
 * Materialized once: keep the main game interactive without network/CDN requests.
 */
(()=>{
  'use strict';
  const encoded={"curator_atlas":"data:image/webp;base64,","castle_facade":"data:image/webp;base64,","ornate_stone":"data:image/webp;base64,","slate_roof":"data:image/webp;base64,","flower_border":"data:image/webp;base64,","night_skyline":"data:image/webp;base64,","distant_city":"data:image/webp;base64,"};
  const images={};
  for(const [name,url] of Object.entries(encoded)){
    const image=new Image();image.decoding='async';image.src=url;images[name]=image;
  }
  window.OIBUNG_CINEMATIC_ART={images,ready(name){const i=images[name];return !!(i&&i.complete&&i.naturalWidth);}};
})();